80	    private Integer possibleDuplicateOf;
81	
82	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
83	    private Set<Pet> pets;
84	
85	    public String getAddress() {
86	        return this.address;
87	    }
88	
89	    public void setAddress(String address) {
90	        this.address = address;
91	    }
92	
93	    public String getCity() {
94	        return this.city;
95	    }
96	
97	    public void setCity(String city) {
98	        this.city = city;
99	    }
100	
101	    public String getTelephone() {
102	        return this.telephone;
103	    }
104	
105	    public void setTelephone(String telephone) {
106	        this.telephone = telephone;
107	    }
108	
109	    public String getEmail() {
110	        return this.email;
111	    }
112	
113	    public void setEmail(String email) {
114	        this.email = email;
115	    }
116	
117	    public LocalDate getRegistrationDate() {
118	        return this.registrationDate;
119	    }
