126	        return this.birthDate;
127	    }
128	
129	    public void setBirthDate(LocalDate birthDate) {
130	        this.birthDate = birthDate;
131	    }
132	
133	    public String getCustomerCode() {
134	        return this.customerCode;
135	    }
136	
137	    public void setCustomerCode(String customerCode) {
138	        this.customerCode = customerCode;
139	    }
