165	    /**
166	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
167	     * Not persisted — derived from {@link #getLastName()} and {@link #getFirstName()}.
168	     */
169	    @Transient
170	    public String getDisplayName() {
171	        return this.getLastName() + ", " + this.getFirstName();
172	    }
173	
174	    /**
175	     * The owner's initials: the upper-cased first letters of firstName and lastName,
176	     * dot-separated with a trailing dot (e.g. {@code 'J.S.'}).
177	     * Not persisted — derived from {@link #getFirstName()} and {@link #getLastName()}.
178	     */
179	    @Transient
180	    public String getInitials() {
181	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
182	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
183	    }
184	
185	    /**
186	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is
187	     * the last two digits of the {@link #getRegistrationDate() registrationDate} year
188	     * (e.g. {@code 'NSW-1A2B3C4D-M26'}).
189	     * Not persisted — derived from {@link #getCustomerCode()} and {@link #getRegistrationDate()}.
190	     */
191	    @Transient
192	    public String getMembershipNumber() {
193	        return this.customerCode + "-M" + String.format("%02d", this.registrationDate.getYear() % 100);
194	    }
195	
196	    /**
197	     * The owner's check digit: the Luhn check digit (0-9) computed over the digits contained
198	     * in the {@link #getCustomerCode() customerCode}. Non-digit characters are ignored.
199	     * Not persisted — derived from {@link #getCustomerCode()}.
200	     */
201	    @Transient
202	    public int getCheckDigit() {
203	        int sum = 0;
204	        boolean dbl = true;
205	        String code = this.customerCode == null ? "" : this.customerCode;
206	        for (int i = code.length() - 1; i >= 0; i--) {
207	            char c = code.charAt(i);
208	            if (c < '0' || c > '9') {
209	                continue;
210	            }
211	            int d = c - '0';
212	            if (dbl) {
213	                d *= 2;
214	                if (d > 9) {
215	                    d -= 9;
216	                }
217	            }
218	            sum += d;
219	            dbl = !dbl;
220	        }
221	        return (10 - (sum % 10)) % 10;
222	    }
223	
224	    /**
225	     * The owner's numeric membership level, fixed at creation. Starts at {@code 1}; adds {@code 1}
226	     * when an {@link #getEmail() email} is present; adds {@code 1} when {@link #getNamesakeCount()
227	     * namesakeCount} is {@code 0}; capped at {@code 3} (level {@code 4} is reserved for tenure).
228	     * Not persisted — derived from {@link #getEmail()} and {@link #getNamesakeCount()}.
229	     */
230	    @Transient
231	    public int getMembershipLevel() {
232	        int level = 1;
233	        boolean hasEmail = this.email != null && !this.email.isBlank();
234	        if (hasEmail) {
235	            level++;
236	        }
237	        boolean uniqueName = this.namesakeCount != null && this.namesakeCount == 0;
238	        if (uniqueName) {
239	            level++;
240	        }
241	        return Math.min(level, 3);
242	    }
243	
244	    /**
245	     * Fixed city-to-region table used as the fall-back when deriving an owner's region.
246	     */
247	    private static final Map<String, String> CITY_REGION = Map.of(
248	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
249	
250	    /**
251	     * Region -> inclusive 4-digit postcode range {low, high}, the primary source for
252	     * deriving an owner's region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
253	     */
254	    private static final Map<String, int[]> REGION_RANGE = Map.of(
255	        "NSW", new int[] {2000, 2099},
256	        "VIC", new int[] {3000, 3099},
257	        "QLD", new int[] {4000, 4099});
258	
259	    /**
260	     * The canonical region for a postcode/city pair, derived first from {@code postcode} by range
261	     * ({@link #regionForPostcode}), falling back to the fixed city table ({@link #regionForCity})
262	     * when the postcode is absent or in no known range, or {@code 'UNKNOWN'} when neither matches.
263	     * Preferring the postcode disambiguates cities that share a name. This is the REGION prefix of
264	     * the owner's {@link #getCustomerCode() customerCode}, so the create pipeline and
265	     * {@link #getLocality() locality} agree on it. The single authority on the region rule, reused
266	     * by the owner pipelines (e.g. postcode validation) rather than copied.
267	     */
268	    public static String regionFor(String postcode, String city) {
269	        String region = regionForPostcode(postcode);
270	        if (region != null) {
271	            return region;
272	        }
273	        String cityRegion = regionForCity(city);
274	        return cityRegion != null ? cityRegion : "UNKNOWN";
275	    }
276	
277	    /** The canonical region for a city by exact name match (Sydney->NSW, Melbourne->VIC,
278	     * Brisbane->QLD), or {@code null} when the city has no known region. */
279	    public static String regionForCity(String city) {
280	        return city == null ? null : CITY_REGION.get(city);
281	    }
282	
283	    /** Region whose inclusive range contains the given postcode (NSW 2000-2099, VIC 3000-3099,
284	     * QLD 4000-4099), or {@code null} when the postcode is absent, not 4 digits, or in no known
285	     * range. */
286	    public static String regionForPostcode(String postcode) {
287	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
288	            return null;
289	        }
290	        int value = Integer.parseInt(postcode);
291	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
292	            int[] range = entry.getValue();
293	            if (value >= range[0] && value <= range[1]) {
294	                return entry.getKey();
295	            }
296	        }
297	        return null;
298	    }
299	
300	    /**
301	     * The owner's locality: the REGION prefix of the {@link #getCustomerCode() customerCode}
302	     * (the portion before the first {@code '-'}), which the create pipeline derives from the
303	     * postcode-and-city region. {@code 'UNKNOWN'} when no customerCode is set. Not persisted —
304	     * derived from {@link #getCustomerCode()}.
305	     */
306	    @Transient
307	    public String getLocality() {
308	        if (this.customerCode == null) {
309	            return "UNKNOWN";
310	        }
311	        int dash = this.customerCode.indexOf('-');
312	        return dash <= 0 ? "UNKNOWN" : this.customerCode.substring(0, dash);
313	    }
314	
315	    /**
316	     * Whether more than 80 owners had already been created today when this response was
317	     * built. Not persisted — populated for the response by the create and fetch pipelines
318	     * and defaults to {@code false} so every owner serialization carries the flag.
319	     */
320	    @Transient
321	    public boolean isBulkSignupWarning() {
322	        return this.bulkSignupWarning;
323	    }
324	
325	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
326	        this.bulkSignupWarning = bulkSignupWarning;
327	    }
328	
329	    /**
330	     * Whether this owner is a possible (soft) duplicate: not a hard duplicate, but shares an
331	     * existing owner's last name and postcode with a different telephone. Not persisted —
332	     * populated for the response by the create and fetch pipelines and defaults to
333	     * {@code false} so every owner serialization carries the flag.
334	     */
335	    @Transient
336	    public boolean isPossibleDuplicate() {
337	        return this.possibleDuplicate;
338	    }
339	
340	    public void setPossibleDuplicate(boolean possibleDuplicate) {
341	        this.possibleDuplicate = possibleDuplicate;
342	    }
343	
344	    /**
345	     * The id of the existing owner this owner possibly duplicates (shared last name and
346	     * postcode, different telephone), or {@code null} when it is not a possible duplicate.
347	     * Not persisted — populated for the response alongside {@link #isPossibleDuplicate()}.
348	     */
349	    @Transient
350	    public Integer getPossibleDuplicateOf() {
351	        return this.possibleDuplicateOf;
352	    }
353	
354	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
355	        this.possibleDuplicateOf = possibleDuplicateOf;
356	    }
357	
358	    /**
359	     * The owner's preferred contact channel: {@code 'EMAIL'} when an {@link #getEmail() email}
360	     * is present, otherwise {@code 'PHONE'}.
361	     * Not persisted — derived from {@link #getEmail()}.
362	     */
363	    @Transient
364	    public String getContactPreference() {
365	        boolean hasEmail = this.email != null && !this.email.isBlank();
366	        return hasEmail ? "EMAIL" : "PHONE";
367	    }
368	
369	    /**
370	     * The owner's age band as of the {@link #getRegistrationDate() registrationDate}, derived
371	     * from {@link #getBirthDate() birthDate}: {@code 'MINOR'} when under 18, {@code 'ADULT'} for
372	     * 18 to 64 inclusive, {@code 'SENIOR'} for 65 and over. {@code null} when no birthDate is
373	     * supplied. Not persisted — derived from {@link #getBirthDate()} and
374	     * {@link #getRegistrationDate()}.
375	     */
376	    @Transient
377	    public String getAgeBand() {
378	        if (this.birthDate == null || this.registrationDate == null) {
379	            return null;
380	        }
381	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
382	        if (age < 18) {
383	            return "MINOR";
384	        }
385	        return age < 65 ? "ADULT" : "SENIOR";
386	    }
387	
388	    protected Set<Pet> getPetsInternal() {
389	        if (this.pets == null) {
390	            this.pets = new HashSet<>();
391	        }
392	        return this.pets;
393	    }
394	
395	    protected void setPetsInternal(Set<Pet> pets) {
396	        this.pets = pets;
397	    }
398	
399	    public List<Pet> getPets() {
400	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
401	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
402	        return Collections.unmodifiableList(sortedPets);
403	    }
404	
405	    public void setPets(List<Pet> pets) {
406	        this.pets = new HashSet<>(pets);
407	    }
408	
409	    public void addPet(Pet pet) {
410	        getPetsInternal().add(pet);
411	        pet.setOwner(this);
412	    }
413	
414	    /**
415	     * Return the Pet with the given name, or null if none found for this Owner.
416	     *
417	     * @param name to test
418	     * @return true if pet name is already in use
419	     */
420	    public Pet getPet(String name) {
421	        return getPet(name, false);
422	    }
423	
424	    /**
425	     * Return the Pet with the given name, or null if none found for this Owner.
426	     *
427	     * @param name to test
428	     * @return true if pet name is already in use
429	     */
430	    public Pet getPet(String name, boolean ignoreNew) {
431	        name = name.toLowerCase();
432	        for (Pet pet : getPetsInternal()) {
433	            if (!ignoreNew || !pet.isNew()) {
434	                String compName = pet.getName();
435	                compName = compName.toLowerCase();
436	                if (compName.equals(name)) {
437	                    return pet;
438	                }
439	            }
440	        }
441	        return null;
442	    }
443	
444	    public Pet getPet(Integer petId) {
445	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
446	    }
447	
448	    @Override
449	    public String toString() {
450	        return new ToStringCreator(this)
451	
452	            .append("id", this.getId())
453	            .append("new", this.isNew())
454	            .append("lastName", this.getLastName())
455	            .append("firstName", this.getFirstName())
456	            .append("address", this.address)
457	            .append("city", this.city)
458	            .append("telephone", this.telephone)
459	            .toString();
460	    }
461	}
